using UnityEngine;
using System.Collections.Generic;
namespace SunnyValley {
 public class ValleyResidents {
  class Resident {public int kind,id;public Vector2 home,p,goal;public float wait;public SpriteView view;}
  readonly List<Resident> residents=new List<Resident>();readonly ValleyGame game;readonly System.Random random=new System.Random(331);
  public ValleyResidents(ValleyGame game,Transform parent,List<SpriteView> views){this.game=game;if(game.State.Room!="outside")return;Vector2[] homes={new Vector2(1100,780),new Vector2(1350,2450),new Vector2(1510,1690),new Vector2(2680,1400),new Vector2(2910,2010),new Vector2(1120,1900),new Vector2(2130,2050),new Vector2(1920,2250)};int[] kinds={0,0,1,1,2,2,3,3},counts={3,2,3,2,4,3,2,2};for(int zone=0;zone<homes.Length;zone++)for(int n=0;n<counts[zone];n++){var r=new Resident{kind=kinds[zone],id=residents.Count,home=homes[zone],p=homes[zone]+new Vector2(n*30,0)};if(!game.State.Walkable(r.p,r.p)){bool found=false;for(int radius=1;radius<6&&!found;radius++)for(int dx=-radius;dx<=radius&&!found;dx++)for(int dy=-radius;dy<=radius;dy++){Vector2 candidate=r.home+new Vector2(dx*48,dy*48);if(game.State.Walkable(candidate,candidate)){r.p=candidate;r.home=candidate;found=true;break;}}}r.goal=r.p;r.view=new SpriteView(parent,"Resident",ReferenceArt.Frame("creatures-v1",0,r.kind,4,4),r.p,new Vector2(48,48));views.Add(r.view);residents.Add(r);}}
  public void Tick(float delta){foreach(var r in residents){bool active=r.kind!=2||game.State.Save.phase<.24f||game.State.Save.phase>.77f;r.view.renderer.enabled=active;if(!active)continue;r.wait-=delta;Vector2 away=r.p-game.player;Vector2 direction=Vector2.zero;if(r.kind==0&&away.magnitude<105)direction=away.normalized;else if(r.wait<=0){direction=(r.goal-r.p).normalized;if(Vector2.Distance(r.goal,r.p)<8){r.wait=(float)random.NextDouble()*2+1;float angle=(float)random.NextDouble()*Mathf.PI*2;r.goal=r.home+new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*(float)random.NextDouble()*100;}}
    foreach(var other in residents)if(other!=r&&Vector2.Distance(other.p,r.p)<35)direction+=(r.p-other.p).normalized*.5f;Vector2 p=r.p+direction*delta*(r.kind==0&&away.magnitude<105?85:28);if(game.State.Walkable(r.p,p))r.p=p;else{r.wait=1;r.goal=r.home;}r.view.Set(ReferenceArt.Frame("creatures-v1",direction.sqrMagnitude>.1f?(int)(Time.time*7)%4:0,r.kind,4,4),new Vector2(48,48));r.view.renderer.flipX=direction.x<0;r.view.Place(r.p);}}
 }
}
